from pathlib import Path

ROOT=Path(__file__).resolve().parents[1]
PORTAL=ROOT/'client-portal/index.html'
CONTRACTS=ROOT/'scripts/validate-repo-contracts.py'
html=PORTAL.read_text(encoding='utf-8')
contracts=CONTRACTS.read_text(encoding='utf-8')

if 'cv-mobile-premium-v36' in html:
    raise SystemExit('v36 already present')

STYLE=r'''\n<style id="cv-mobile-premium-v36">\n/* CV Coach Mobile Premium V36\n   Deep mobile pass: brand presence, safe header, legibility, navigation and technique sheet. */\n@media(max-width:767px){\n  :root{--cvm-text:#f7f9fa;--cvm-muted:#a9b4bb;--cvm-blue:#43b8ff;--cvm-green:#5ee3a5}\n\n  /* Two-level mobile header: brand/actions first, identity second. */\n  .top{\n    position:sticky!important;top:0!important;z-index:150!important;\n    min-height:112px!important;height:auto!important;\n    padding:calc(10px + env(safe-area-inset-top)) 14px 10px!important;\n    display:grid!important;grid-template-columns:minmax(110px,1fr) auto!important;grid-template-rows:52px auto!important;\n    column-gap:10px!important;row-gap:5px!important;align-items:center!important;\n    background:linear-gradient(180deg,rgba(2,6,8,.995),rgba(4,9,12,.985))!important;\n    border-bottom:1px solid #25333b!important;box-shadow:0 12px 34px rgba(0,0,0,.42)!important;\n  }\n  .top .cvOfficialHeaderImg{\n    grid-column:1!important;grid-row:1!important;justify-self:start!important;\n    width:116px!important;height:52px!important;max-width:116px!important;object-fit:contain!important;object-position:left center!important;\n    filter:drop-shadow(0 7px 16px rgba(0,0,0,.58)) drop-shadow(0 0 11px rgba(225,29,46,.16))!important;\n  }\n  .top .cvHeaderIdentity,.top .topTitle{\n    grid-column:1/-1!important;grid-row:2!important;justify-self:center!important;width:100%!important;\n    text-align:center!important;margin:0!important;padding:2px 8px 0!important;\n  }\n  .cvHeaderIdentity b{font-size:15px!important;line-height:1.05!important;letter-spacing:.025em!important;color:#fff!important;white-space:nowrap!important;overflow:hidden!important;text-overflow:ellipsis!important}\n  .cvHeaderIdentity small{margin-top:5px!important;font-size:8px!important;line-height:1.2!important;letter-spacing:.11em!important;color:#9aa7ae!important}\n  .topRight{\n    grid-column:2!important;grid-row:1!important;justify-self:end!important;width:auto!important;margin:0!important;\n    display:flex!important;align-items:center!important;gap:7px!important;\n  }\n  .demoBadge{min-height:34px!important;padding:0 9px!important;display:inline-flex!important;align-items:center!important;font-size:9px!important;letter-spacing:.035em!important;margin:0!important}\n  .cvNotificationButton,.cvSoundToggle{width:40px!important;height:40px!important;min-height:40px!important;border-radius:12px!important;font-size:18px!important;background:#0b141a!important;border-color:#30414b!important}\n  .cvNotificationBadge{top:-5px!important;right:-5px!important;min-width:18px!important;height:18px!important;font-size:9px!important}\n  .logout{min-height:40px!important;padding:0 8px!important;border:1px solid #2b3942!important;border-radius:11px!important;background:#0a1116!important;color:#d8dfe3!important;font-size:10px!important;font-weight:800!important}\n\n  /* General mobile text scale: eliminate microcopy that requires squinting. */\n  .content{padding:16px 16px calc(104px + env(safe-area-inset-bottom))!important}\n  .sub{font-size:14px!important;line-height:1.5!important;color:#b3bec4!important}\n  .hint{font-size:12px!important;line-height:1.48!important;color:#9eabb2!important}\n  .ey{font-size:11px!important;line-height:1.2!important;letter-spacing:.18em!important}\n  .sectionHead .link{font-size:12px!important;padding:6px 0!important}\n  .section h2{font-size:28px!important;line-height:1.05!important}\n  .card{border-radius:17px!important}\n  .btn{font-size:13px!important;min-height:48px!important}\n\n  /* Home: preserve cinematic hierarchy but improve reading size. */\n  .hero{min-height:230px!important;padding:20px 20px 21px!important;border-radius:20px!important}\n  .hero h1{font-size:36px!important;line-height:.94!important;max-width:90%!important}\n  .hero .sub{font-size:14px!important;max-width:88%!important}\n  .stats{gap:8px!important}.stat{min-height:84px!important;padding:12px 11px!important;border-radius:15px!important}\n  .stat .l{font-size:9.5px!important;line-height:1.2!important}.stat .v{font-size:30px!important;margin-top:7px!important}\n  .next{padding:18px 120px 18px 18px!important;min-height:166px!important}.next h3{font-size:27px!important;line-height:1.08!important}.next .hint{font-size:12px!important}.next:after{width:92px!important;height:92px!important;right:16px!important}\n  .mission,.habit{padding:15px 0!important}.mission b,.habit b{font-size:15px!important}.mission .hint,.habit .hint{font-size:11.5px!important;margin-top:3px!important}\n\n  /* Workout labels and information. */\n  .cvWorkoutHeroV31{padding:20px 18px 18px!important}.cvWorkoutHeroEy{font-size:10.5px!important}.cvWorkoutLivePill{font-size:9px!important;padding:7px 10px!important}\n  .cvWorkoutHeroV31 h1{font-size:38px!important}.cvWorkoutHeroFocus{font-size:14px!important}.cvWorkoutHeroChip{font-size:10px!important;min-height:31px!important;padding:0 10px!important}.cvWorkoutProgressCopy{font-size:10.5px!important}\n  body.cvFastWorkout .cvSessionStat small{font-size:10.5px!important}.cvSessionStat b{font-size:27px!important}\n  body.cvFastWorkout .exerciseTop h3{font-size:27px!important;line-height:1.05!important}\n  .cvExecutionBtnV35{min-height:36px!important;padding:0 11px!important;border-radius:10px!important;font-size:9px!important;letter-spacing:.055em!important}\n  .cvPrescriptionChip{font-size:9.5px!important;min-height:27px!important;padding:0 9px!important}\n  body.cvFastWorkout .cvHevyExercise>.cvRestText{font-size:10.5px!important;padding:7px 10px!important}\n  body.cvFastWorkout .cvSetsHead span{font-size:10.5px!important}.cvPrevMain{font-size:15px!important}.cvPrevMeta{font-size:8.5px!important}.cvAddSet{font-size:14px!important}\n\n  /* Technique sheet: readable enough to use between sets. */\n  .cvTechSheet{padding:14px 18px calc(28px + env(safe-area-inset-bottom))!important;max-height:91dvh!important;border-radius:24px 24px 0 0!important}\n  .cvTechHandle{width:54px!important;height:5px!important;margin-bottom:15px!important}\n  .cvTechHead{gap:12px!important;margin-bottom:14px!important}.cvTechHead h2{font-size:36px!important;line-height:1.02!important}.cvTechClose{width:46px!important;height:46px!important;font-size:26px!important}\n  .cvTechMedia{min-height:190px!important;border-radius:15px!important;margin-bottom:14px!important}.cvTechMedia img{max-height:50vh!important}\n  .cvTechBlock{padding:16px!important;border-radius:15px!important;margin-top:12px!important}.cvTechBlock h4{font-size:12px!important;letter-spacing:.11em!important;margin-bottom:10px!important}.cvTechBlock p{font-size:16.5px!important;line-height:1.62!important;color:#e0e6e9!important}\n  .cvTechTempo{font-size:14px!important;line-height:1.6!important;margin-top:14px!important;padding-top:13px!important}.cvTempoHumanTitle{font-size:11px!important;margin-bottom:9px!important}.cvTempoStep{grid-template-columns:32px minmax(0,1fr) 52px!important;min-height:48px!important;gap:9px!important}.cvTempoStep .n{width:30px!important;height:30px!important;font-size:13px!important}.cvTempoStep .copy strong{font-size:11.5px!important}.cvTempoStep .copy small{font-size:9.5px!important;line-height:1.4!important}.cvTempoStep .secs{font-size:18px!important}.cvTempoHelp{font-size:10px!important;line-height:1.5!important;padding:9px 10px!important}\n\n  /* Bottom nav becomes a strong primary control on phone. */\n  .nav{height:86px!important;min-height:86px!important;padding:7px 7px calc(7px + env(safe-area-inset-bottom))!important;background:rgba(2,5,7,.992)!important;border-top:1px solid #2a3740!important;box-shadow:0 -18px 48px rgba(0,0,0,.66)!important}\n  .nav button{min-height:66px!important;gap:6px!important;font-size:11.5px!important;font-weight:800!important;color:#87949c!important}\n  .nav .ico,.nav button .ico{font-size:27px!important;line-height:1!important}.nav button .ico svg{width:27px!important;height:27px!important;stroke-width:1.9!important}\n  .nav button.active{color:#fff!important}.nav button.active:after{width:28px!important;height:3px!important;margin-top:4px!important}\n\n  /* Achievements/progress should look like meaningful product, not microcopy. */\n  .achievementSummary{gap:8px!important}.achievementSummary .stat{min-height:80px!important}.achievementCard{padding:16px!important}.achievementCard h3{font-size:26px!important}.achievementCard p{font-size:13px!important;line-height:1.55!important}.achievementTag{font-size:9px!important;padding:5px 8px!important}.achievementReward{font-size:11.5px!important;line-height:1.45!important}.achievementDate{font-size:10.5px!important}.achievementWarning,.achievementLoading{font-size:12px!important;line-height:1.45!important}\n}\n\n@media(max-width:390px){\n  .top{grid-template-columns:minmax(96px,1fr) auto!important;padding-left:10px!important;padding-right:10px!important}.top .cvOfficialHeaderImg{width:103px!important;max-width:103px!important}.topRight{gap:4px!important}.cvNotificationButton,.cvSoundToggle{width:37px!important;height:37px!important;min-height:37px!important}.logout{padding:0 6px!important;font-size:9px!important}.demoBadge{padding:0 7px!important;font-size:8px!important}\n  .nav button{font-size:10.5px!important}.nav .ico,.nav button .ico{font-size:25px!important}.nav button .ico svg{width:25px!important;height:25px!important}\n  .cvTechHead h2{font-size:33px!important}.cvTechBlock p{font-size:15.5px!important}.cvTechTempo{font-size:13.5px!important}\n}\n</style>\n'''

JS=r'''\n<script id="cv-mobile-premium-v36-js">\n(function(){\n  function mobileA11y(){\n    const logo=document.querySelector('.top .cvOfficialHeaderImg');\n    if(logo){logo.alt='Camilo Vásquez Fitness Coach';logo.setAttribute('aria-label','Camilo Vásquez Fitness Coach')}\n    const logout=document.getElementById('logout');if(logout){logout.setAttribute('aria-label','Cerrar sesión');logout.title='Cerrar sesión'}\n    const sound=document.getElementById('cvSoundToggle');if(sound)sound.setAttribute('aria-label',sound.classList.contains('off')?'Activar sonido':'Desactivar sonido');\n    document.querySelectorAll('.nav button').forEach(b=>b.setAttribute('aria-label',b.textContent.trim()));\n  }\n  const baseRender=window.render;window.render=function(){const r=baseRender.apply(this,arguments);requestAnimationFrame(mobileA11y);return r};\n  requestAnimationFrame(mobileA11y);\n})();\n</script>\n'''

anchor='\n</body></html>'
if anchor not in html:
    raise SystemExit('closing body anchor missing')
html=html.replace(anchor,STYLE+JS+anchor,1)

# Small regression markers if validator owns portal contract checks.
if 'cv-mobile-premium-v36' not in contracts:
    marker='print("REPO_CONTRACTS_OK")'
    if marker in contracts:
        contracts=contracts.replace(marker,'require(client_portal, "cv-mobile-premium-v36", "mobile premium design layer")\nrequire(client_portal, "cvTechBlock p", "technique readable typography")\n'+marker,1)

PORTAL.write_text(html,encoding='utf-8')
CONTRACTS.write_text(contracts,encoding='utf-8')
print('MOBILE_PREMIUM_V36_PATCH_OK')
